PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT UNIQUE NOT NULL, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'CUSTOMER' CHECK(role IN ('CUSTOMER','RESELLER','ADMIN','MAIN_ADMIN')), email_verified INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'ACTIVE', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reseller_applications (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), business_name TEXT, website TEXT, status TEXT NOT NULL DEFAULT 'PENDING', reviewed_by TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS wallets (user_id TEXT PRIMARY KEY REFERENCES users(id), balance_cents INTEGER NOT NULL DEFAULT 0 CHECK(balance_cents >= 0), currency TEXT NOT NULL DEFAULT 'USD');
CREATE TABLE IF NOT EXISTS wallet_transactions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), amount_cents INTEGER NOT NULL, type TEXT NOT NULL, reference TEXT UNIQUE NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY, supplier_id TEXT UNIQUE, title TEXT NOT NULL, category TEXT NOT NULL, product_type TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 0, supplier_payload TEXT, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS product_prices (product_id TEXT NOT NULL REFERENCES products(id), tier TEXT NOT NULL, markup_bps INTEGER NOT NULL DEFAULT 3000, fixed_price_cents INTEGER, PRIMARY KEY(product_id,tier));
CREATE TABLE IF NOT EXISTS orders (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), product_id TEXT NOT NULL REFERENCES products(id), amount_cents INTEGER NOT NULL, supplier_cost_cents INTEGER, status TEXT NOT NULL DEFAULT 'PENDING', supplier_reference TEXT UNIQUE, idempotency_key TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,idempotency_key));
CREATE TABLE IF NOT EXISTS api_credentials (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), label TEXT NOT NULL, key_hash TEXT NOT NULL UNIQUE, prefix TEXT NOT NULL, revoked_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS api_requests (id TEXT PRIMARY KEY, credential_id TEXT REFERENCES api_credentials(id), request_id TEXT UNIQUE NOT NULL, method TEXT NOT NULL, endpoint TEXT NOT NULL, status_code INTEGER, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS deposits (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), amount_cents INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'PENDING', method TEXT NOT NULL, reviewed_by TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS supplier_integrations (id TEXT PRIMARY KEY, supplier TEXT NOT NULL UNIQUE, enabled INTEGER NOT NULL DEFAULT 0, config_json TEXT, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS admin_audit_logs (id TEXT PRIMARY KEY, actor_id TEXT NOT NULL, action TEXT NOT NULL, target_id TEXT, detail_json TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
